def _ign13(k):
    # Зажигание по моторам семейства — из тех же данных, что в приложении
    out = []
    for e in F[k]["engines"]:
        ig = e["v"].get("ign", "")
        if ig and "уточняется" not in ig:
            out.append(f"{E(e['name'])} — {E(ig[0].lower() + ig[1:])}")
    return "Зажигание: " + "; ".join(out) + "." if out else ""

